from flask_sqlalchemy import SQLAlchemy
from datetime import datetime
import threading

db = SQLAlchemy()
INDEX = []

def add_to_index(index_name, obj):
    # Simplified mock index function (not atomic)
    INDEX.append((index_name, obj.id, obj.body))

class SearchableMixin(object):
    @classmethod
    def before_commit(cls, session):
        # Problem 1 & 2: does not clear residual _changes from previous transactions
        # Problem 3: attaches shared mutable state directly to global session
        session._changes = {
            'add': [obj for obj in session.new if isinstance(obj, cls)],
            'update': [obj for obj in session.dirty if isinstance(obj, cls)],
            'delete': [obj for obj in session.deleted if isinstance(obj, cls)]
        }

    @classmethod
    def after_commit(cls, session):
        # Problem 1: no existence or type check for _changes
        for obj in session._changes['add']:
            add_to_index(cls.__tablename__, obj)
        for obj in session._changes['update']:
            add_to_index(cls.__tablename__, obj)
        for obj in session._changes['delete']:
            add_to_index(cls.__tablename__, obj)
        # Problem 2: no cleanup after commit, leaving stale data in _changes

class Post(SearchableMixin, db.Model):
    __tablename__ = 'post'
    id = db.Column(db.Integer, primary_key=True)
    body = db.Column(db.String(140))
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)

# Problem 6: uses global db.session event registration instead of SQLAlchemy SessionEvents

db.event.listen(db.session, 'before_commit', Post.before_commit)
db.event.listen(db.session, 'after_commit', Post.after_commit)
